// Real requests: what the pilots' model seats (mayor, planning officer, finance officer; gpt-6-sol and gpt-6.1-sol)
// actually asked for with `do`, word for word, with the answer that is right under the rules as they are written
// today (translatorSystem(), contracts/calls.md). Taken from the runs' logs with `oikos corpus` (2026-10-06).
//
// Every case here is SEEN: real pilot requests are for style and for testing, and may be read and tuned on. They are
// not training data as they stand (the answers were decided by hand, case by case), and the held-out cases are
// elsewhere (held-out.ts).
//
// How the answers were decided:
//   - the pilot's draft was confirmed by the seat and applied by the kernel: that call, checked against today's rules
//     and corrected where they say otherwise (the note says what changed);
//   - the draft was declined, or no draft came back: what the request should become today, a program or a refusal;
//   - (2026-10-08: a hold, an entry on one's own file and the label look_first were added to the call language,
//     docs/design/call-language-gaps.md. The cases with gap `pause`, `unnamed_record`, `look_then_act` and
//     `ledger_entry` keep the gap's name, for what was missing when they were asked, and are keyed to what is right
//     now; each one's note says what changed.)
//   - nothing in the call language can say it: `gap` names what is missing (GAPS below), and the answer is the
//     refusal the rules call for, none(no_such_act) mostly. (Until that label existed, 2026-10-06, any refusal was
//     accepted for these.) Where a request is half sayable (something no call does, and something one does), the
//     rule is the refusal: the part isn't written for the whole. A second answer is kept only where the request
//     can fairly be read as asking for the sayable thing alone, and the note says how.
//
// These requests name the ids of their own towns, so an answer can't be checked by resolving it against the test
// town (run.ts, `fixture()`). They are scored by shape instead (pilot-run.ts, `passesReal`): the same functions and
// argument names, every id and amount equal, and the arguments in `ignore` (a law's words, a letter) not compared.

import type { Knowledge } from "../src/knowledge";

export interface RealCase {
  id: string;
  /** Where it came from: the run's folder, the seat that asked, the day, and the draft's id in that run's log. */
  from: { run: string; seat: string; day: number; draft: string };
  /** What became of it in the pilot: `applied` (drafted, confirmed, carried out), `declined` (drafted, and the seat
   * said no), `failed` (no draft came back), `stopped_the_run` (its draft broke the log's contract). */
  pilot: "applied" | "confirmed" | "declined" | "drafted" | "failed" | "stopped_the_run";
  /** The forms the seat knew when it asked (FORMS below): the translator is shown them, as in the run. */
  forms?: keyof typeof FORMS;
  request: string;
  /** The right answers. In a program, "…" stands for text that isn't compared (as a letter's `to`: anyone). */
  expect: string[];
  /** Arguments that aren't compared, present or not. */
  ignore?: string[];
  /** What the request asks for that the call language can't say (a name in GAPS). */
  gap?: Extract<keyof typeof GAPS, string>;
  note?: string;
}

type FormRecord = Knowledge["forms"][number];
const form = (id: string, name: string, fields: { [k: string]: { type: string; required?: boolean; options?: string[] } }): FormRecord =>
  ({ id, record: "statement", author: "genesis", at: 0, visible_to: "public", speaks_for: "city", kind: "form", text: `${name.replace(/_/g, " ")}.`, data: { form: name, submit_as: name, submit_to: ["city"], fields: Object.fromEntries(Object.entries(fields).sort(([a], [b]) => (a < b ? -1 : 1))) } }) as FormRecord;
const amount = { type: "amount" };
const PROPOSAL = { affects: { type: "choice", options: ["tenants", "development", "neither"] }, kind: { type: "choice", options: ["law", "budget", "other"], required: true }, proposal: { type: "text", required: true } };
const PERMIT = form("form-permit", "permit_application", { lot: { type: "lot", required: true }, notes: { type: "text" }, structure_type: { type: "structure_type", required: true } });

/** The forms the pilots' seats knew, as the translator was shown them (the logs' transcripts): the council proposal
 * had three budget lines until pilot 7b found two missing (docs/real-models.md), five since. */
export const FORMS = {
  narrow: [form("form-council-proposal", "council_proposal", { ...PROPOSAL, parks: amount, services: amount, staff: amount }), PERMIT],
  wide: [form("form-council-proposal", "council_proposal", { ...PROPOSAL, environment: amount, parks: amount, roads: amount, services: amount, staff: amount }), PERMIT],
};

/** What these requests ask for that can't be said: each gap, by the name the cases use. */
export const GAPS: { [name: string]: string } = {
  pause: "Holding a standing arrangement and letting it go again: a recurring payment (or any standing request) can be made (money(every=…)) and withdrawn for good (statement(withdraw=…)), but not suspended and resumed.",
  unnamed_record: "A record known only by what it is (\"any standing instruction paying $2,393.34 from acc-city to acc-c0003\"): a call can name a record only by its id; people and things can be named by description, records can't be found by theirs.",
  own_practice: "Changing what one's own organisation does by itself (stop advertising vacancies, stop signing new agreements automatically): there is no call for an office's standing practice unless it is a separate system with an id (system(retire=…) switches a whole system off for good).",
  go_and_see: "Going somewhere in person to see and getting back what was seen (visit a house, attend a records examination, inspect a hall): no call sends the seat, or anyone, to look and report; work(...) needs a task the world defines.",
  look_then_act: "An act whose content depends on what a look finds first (review the records, then send the findings; identify the officeholder, then forward the letter to them): a program is fixed when it is written and can't carry a result from reading into a later line.",
  ledger_entry: "An entry in an organisation's own books that moves no money (tax withheld recorded as payable, a payment charged to a budget line): a call can pay, and can publish a statement, but nothing writes a line in a ledger.",
};

